<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --issuer-uri</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://token.actions.githubusercontent.com&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
